{
  "candidates": [
    {
      "claimType": "recurringBehavior",
      "statement": "该用户在每个工作日的中午有下楼购买咖啡的习惯。",
      "supportingRefs": [
        "o2"
      ],
      "alternativeExplanations": [
        "用户仅在特定几天（如周一、周五）购买，而非每天",
        "购买地点并非严格意义上的“下楼”，而是附近其他店铺"
      ],
      "verificationPlan": [
        {
          "op": "retrieveRelated",
          "question": "检索过去一个月所有 finance 域中概念为“咖啡”且 attribution 为 self 的记录，检查其 recordedAt 或 occurredAt 是否集中在工作日中午时段"
        },
        {
          "op": "searchCounterEvidence",
          "question": "是否存在工作日中午购买了非咖啡类饮品但被归类为咖啡的异常记录，或完全未购买咖啡的工作日"
        }
      ],
      "whatWouldChangeTheAnswer": "若发现购买时间分散在早晚或非工作日，则命题不成立；若发现仅偶尔购买，则从“习惯”降级为“偶发行为”。",
      "evidenceGrade": "支持",
      "action": "adopt"
    },
    {
      "claimType": "conditionalAssociation",
      "statement": "用户的咖啡消费与工作日的办公场景存在强关联。",
      "supportingRefs": [
        "o1",
        "o2"
      ],
      "alternativeExplanations": [
        "用户可能在周末也购买咖啡，但仅在工作日集中记账",
        "“上班”仅为语境修饰，实际购买行为与通勤或居家无关"
      ],
      "verificationPlan": [
        {
          "op": "comparePeriods",
          "question": "对比工作日与非工作日（周末/节假日）的咖啡购买频次，验证是否显著高于非工作日"
        },
        {
          "op": "alignEvents",
          "question": "将咖啡购买时间与用户的位置数据（如有）或日程事件对齐，确认是否发生在办公区域附近"
        }
      ],
      "whatWouldChangeTheAnswer": "若周末购买频次与工作日持平，则条件性关联减弱；若发现购买地点多在居住区，则关联对象变为“居家”而非“办公”。",
      "evidenceGrade": "线索",
      "action": "ask"
    }
  ]
}
